styles:
    /* ── Reset & Base ─────────────────────────────── */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    html { scroll-behavior: smooth; }
    body {
      font-family: 'Inter', sans-serif;
      background: #fff;
      color: #1c1917;
      overflow-x: hidden;
      line-height: 1.6;
    }
    img { max-width: 100%; display: block; }
    a { text-decoration: none; }

    /* ── Scroll Progress Bar ──────────────────────── */
    #scroll-progress {
      position: fixed; top: 0; left: 0;
      width: 0%; height: 3px;
      background: linear-gradient(to right, #fbbf24, #78716c, #34d399);
      z-index: 9999;
      transition: width 0.1s linear;
    }

    /* ── Header ───────────────────────────────────── */
    header {
      position: fixed; top: 3px; left: 0; right: 0;
      z-index: 1000;
      transition: all 0.5s ease;
      background: #262626;
    }
    header.scrolled {
      background: rgba(255,255,255,0.97);
      backdrop-filter: blur(20px);
      box-shadow: 0 4px 32px rgba(0,0,0,0.12);
      border-bottom: 1px solid rgba(214,211,209,0.5);
    }
    .header-inner {
      max-width: 1280px; margin: 0 auto;
      padding: 1rem 1.5rem;
      display: flex; align-items: center; justify-content: space-between;
    }
    .logo {
      display: flex; align-items: center; gap: 0.75rem;
      cursor: pointer; text-decoration: none;
    }
    .logo-icon {
      padding: 0.625rem;
      border-radius: 1rem;
      background: rgba(255,255,255,0.15);
      border: 1px solid rgba(255,255,255,0.3);
      transition: all 0.3s;
    }
    header.scrolled .logo-icon {
      background: linear-gradient(135deg, #44403c, #1e293b);
      border: none;
    }
    .logo-icon svg { width: 1.5rem; height: 1.5rem; }
    .logo-icon svg path { transition: stroke 0.3s; }
    header:not(.scrolled) .logo-icon svg path { stroke: #000; }
    header.scrolled .logo-icon svg path { stroke: #fff; }
    .logo-text { line-height: 1.2; }
    .logo-name {
      font-size: 1.125rem; font-weight: 700;
      color: #fff; transition: color 0.3s;
    }
    header.scrolled .logo-name { color: #1c1917; }
    .logo-sub {
      font-size: 0.7rem; font-weight: 500;
      color: #d6d3d1; transition: color 0.3s;
    }
    header.scrolled .logo-sub { color: #78716c; }
    nav { display: flex; align-items: center; gap: 2rem; }
    nav a {
      font-weight: 600; font-size: 0.925rem;
      color: #fff; transition: color 0.3s;
      position: relative;
    }
    header.scrolled nav a { color: #44403c; }
    nav a::after {
      content: ''; position: absolute; bottom: -2px; left: 0;
      width: 0; height: 2px; background: #1c1917;
      transition: width 0.3s;
    }
    header.scrolled nav a::after { background: #1c1917; }
    header:not(.scrolled) nav a::after { background: #fff; }
    nav a:hover::after { width: 100%; }
    .nav-cta {
      display: flex; align-items: center; gap: 0.4rem;
      padding: 0.625rem 1.25rem;
      background: linear-gradient(135deg, #22c55e, #10b981);
      color: #fff !important; border-radius: 1rem;
      font-weight: 600; font-size: 0.875rem;
      transition: all 0.3s; box-shadow: 0 4px 16px rgba(34,197,94,0.3);
    }
    .nav-cta:hover { background: linear-gradient(135deg, #16a34a, #059669); transform: translateY(-2px); }
    .nav-cta::after { display: none !important; }
    .hamburger {
      display: none; flex-direction: column; gap: 5px;
      cursor: pointer; padding: 0.5rem;
      background: rgba(255,255,255,0.15); border: 1px solid rgba(255,255,255,0.3);
      border-radius: 0.75rem;
    }
    header.scrolled .hamburger { background: #f5f5f4; border-color: transparent; }
    .hamburger span {
      width: 20px; height: 2px; background: #fff;
      border-radius: 2px; transition: all 0.3s;
    }
    header.scrolled .hamburger span { background: #1c1917; }
    .mobile-nav {
      display: none; padding: 1rem 0;
      border-top: 1px solid rgba(255,255,255,0.2);
      margin-top: 0.75rem;
    }
    header.scrolled .mobile-nav { border-color: #e7e5e4; }
    .mobile-nav.open { display: block; }
    .mobile-nav a {
      display: block; padding: 0.75rem 1rem;
      color: #fff; font-weight: 600; border-radius: 0.75rem;
      transition: all 0.2s;
    }
    header.scrolled .mobile-nav a { color: #44403c; }
    .mobile-nav a:hover { background: rgba(255,255,255,0.1); padding-left: 1.5rem; }
    .mobile-cta-wrap { margin-top: 0.75rem; }
    .mobile-cta {
      display: flex; align-items: center; justify-content: center; gap: 0.5rem;
      padding: 1rem; background: linear-gradient(135deg, #22c55e, #10b981);
      color: #fff !important; border-radius: 1rem; font-weight: 600;
    }

    @media (max-width: 768px) {
      nav { display: none; }
      .hamburger { display: flex; }
    }

    /* ── Hero Image ───────────────────────────────── */
    .hero-image {
      position: relative; height: 260px; overflow: hidden;
      margin-top: 3px;
    }
    @media (min-width: 768px) { .hero-image { height: 380px; } }
    .hero-image img { width: 100%; height: 100%; object-fit: cover; }
    .hero-overlay {
      position: absolute; inset: 0;
      background: linear-gradient(to top, rgba(0,0,0,0.7) 0%, rgba(0,0,0,0.3) 50%, transparent 100%);
    }
    .hero-badge {
      position: absolute; bottom: 1.5rem; left: 1.5rem;
      padding: 0.25rem 0.75rem;
      background: rgba(255,255,255,0.92); backdrop-filter: blur(8px);
      color: #1c1917; border-radius: 9999px;
      font-size: 0.75rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em;
    }

    /* ── Page Layout ──────────────────────────────── */
    .page-wrap {
      max-width: 64rem; margin: 0 auto;
      padding: 3rem 1.5rem;
    }

    /* ── Back Button ──────────────────────────────── */
    .back-btn {
      display: inline-flex; align-items: center; gap: 0.5rem;
      color: #78716c; font-size: 0.875rem; font-weight: 500;
      margin-bottom: 2rem; transition: color 0.2s;
      cursor: pointer; background: none; border: none;
    }
    .back-btn:hover { color: #1c1917; transform: translateX(-4px); }
    .back-btn svg { width: 1rem; height: 1rem; }

    /* ── Post Meta ────────────────────────────────── */
    .post-meta {
      display: flex; flex-wrap: wrap; gap: 1rem;
      margin-bottom: 1.5rem;
      font-size: 0.875rem; color: #78716c;
    }
    .post-meta span { display: flex; align-items: center; gap: 0.25rem; }
    .post-meta svg { width: 1rem; height: 1rem; }

    /* ── Post Title & Excerpt ─────────────────────── */
    .post-title {
      font-size: clamp(1.75rem, 4vw, 3rem);
      font-weight: 800; color: #1c1917; line-height: 1.2;
      margin-bottom: 1.25rem;
    }
    .post-excerpt {
      font-size: 1.125rem; color: #78716c; line-height: 1.75;
      border-left: 4px solid #fbbf24; padding-left: 1rem;
      margin-bottom: 2rem;
    }

    /* ── Tags ─────────────────────────────────────── */
    .tags { display: flex; flex-wrap: wrap; gap: 0.5rem; margin-bottom: 2.5rem; }
    .tag {
      display: inline-flex; align-items: center; gap: 0.25rem;
      padding: 0.25rem 0.75rem;
      background: #f5f5f4; color: #57534e; border-radius: 9999px;
      font-size: 0.75rem; font-weight: 500;
    }
    .tag svg { width: 0.75rem; height: 0.75rem; }

    /* ── Prose ────────────────────────────────────── */
    .prose h2 {
      font-size: 1.5rem; font-weight: 700; color: #1c1917;
      margin-top: 2.5rem; margin-bottom: 1rem;
      padding-bottom: 0.5rem; border-bottom: 1px solid #f5f5f4;
      scroll-margin-top: 6rem;
    }
    .prose h3 {
      font-size: 1.25rem; font-weight: 700; color: #292524;
      margin-top: 2rem; margin-bottom: 0.75rem;
      scroll-margin-top: 6rem;
    }
    .prose h4 { font-size: 1.125rem; font-weight: 700; color: #292524; margin-top: 1.5rem; margin-bottom: 0.5rem; }
    .prose p { color: #44403c; line-height: 1.75; margin-bottom: 1rem; font-size: 1rem; }
    .prose ul { list-style: disc; padding-left: 1.5rem; margin-bottom: 1rem; color: #44403c; }
    .prose ol { list-style: decimal; padding-left: 1.5rem; margin-bottom: 1rem; color: #44403c; }
    .prose li { line-height: 1.75; margin-bottom: 0.5rem; }
    .prose strong { font-weight: 700; color: #1c1917; }
    .prose em { font-style: italic; }
    .prose a { color: #92400e; text-decoration: underline; font-weight: 500; }
    .prose a:hover { color: #78350f; }
    .prose blockquote {
      border-left: 4px solid #fbbf24; padding: 0.75rem 1rem;
      margin: 1rem 0; background: #fffbeb; border-radius: 0 0.75rem 0.75rem 0;
      color: #44403c; font-style: italic;
    }
    .prose hr { margin: 2rem 0; border: none; border-top: 1px solid #e7e5e4; }
    /* GFM tables in prose */
    .prose .table-wrap { overflow-x: auto; border-radius: 1rem; border: 1px solid #e7e5e4; box-shadow: 0 4px 16px rgba(0,0,0,0.06); margin: 1.5rem 0; }
    .prose table { width: 100%; font-size: 0.875rem; border-collapse: collapse; }
    .prose thead { background: #1c1917; color: #fff; }
    .prose th { padding: 0.75rem 1rem; text-align: left; font-weight: 700; white-space: nowrap; }
    .prose tbody tr { border-top: 1px solid #f5f5f4; }
    .prose tbody tr:hover { background: rgba(251,191,36,0.06); }
    .prose tbody tr:nth-child(even) { background: #fafaf9; }
    .prose td { padding: 0.75rem 1rem; color: #44403c; vertical-align: top; }

    /* ── Disclosure Banner ────────────────────────── */
    .disclosure {
      margin: 1.5rem 0; padding: 1rem 1.25rem;
      background: #fffbeb; border: 1px solid #fde68a; border-radius: 1rem;
      font-size: 0.875rem; color: #92400e; line-height: 1.6;
    }
    .disclosure strong { font-weight: 700; }

    /* ── Star Rating ──────────────────────────────── */
    .stars { display: flex; align-items: center; gap: 2px; }
    .star { width: 1rem; height: 1rem; }
    .star.filled { color: #fbbf24; fill: #fbbf24; }
    .star.empty { color: #d6d3d1; }
    .stars-sm .star { width: 0.75rem; height: 0.75rem; }

    /* ── Product Comparison Table ─────────────────── */
    .product-table-wrap {
      overflow-x: auto; border-radius: 1rem;
      border: 1px solid #e7e5e4;
      box-shadow: 0 4px 24px rgba(0,0,0,0.08);
      margin: 2rem 0;
    }
    .product-table { width: 100%; font-size: 0.875rem; border-collapse: collapse; }
    .product-table thead tr { background: #1c1917; color: #fff; }
    .product-table th { padding: 1rem; text-align: left; font-weight: 700; white-space: nowrap; }
    .product-table tbody tr { border-top: 1px solid #f5f5f4; transition: background 0.15s; }
    .product-table tbody tr:nth-child(even) { background: rgba(251,191,36,0.08); }
    .product-table tbody tr:hover { background: #fffbeb; }
    .product-table td { padding: 1rem; vertical-align: middle; }
    .product-table .product-cell { display: flex; align-items: center; gap: 0.75rem; }
    .product-table .product-thumb {
      width: 3rem; height: 3rem; flex-shrink: 0;
      background: #f5f5f4; border: 1px solid #e7e5e4; border-radius: 0.75rem;
      display: flex; align-items: center; justify-content: center; overflow: hidden;
    }
    .product-table .product-thumb img { max-height: 2.5rem; max-width: 100%; object-fit: contain; }
    .product-table .product-name { font-weight: 600; color: #1c1917; }
    .product-table .rating-cell { text-align: center; }
    .product-table .rating-val { font-size: 0.75rem; color: #78716c; margin-top: 2px; }
    .product-table .center { text-align: center; color: #57534e; }
    .product-table .visit-btn {
      display: inline-block; padding: 0.375rem 0.875rem;
      background: linear-gradient(135deg, #22c55e, #10b981);
      color: #fff; border-radius: 0.75rem; font-size: 0.75rem; font-weight: 700;
      transition: all 0.2s;
    }
    .product-table .visit-btn:hover { background: linear-gradient(135deg, #16a34a, #059669); transform: translateY(-1px); }

    /* ── Product Card ─────────────────────────────── */
    .product-card { margin-bottom: 2.5rem; }
    .product-card-inner {
      background: #fff; border-radius: 1.5rem;
      border: 2px solid #f5f5f4;
      box-shadow: 0 4px 24px rgba(0,0,0,0.07);
      overflow: hidden;
      transition: box-shadow 0.3s, transform 0.3s;
    }
    .product-card-inner:hover { box-shadow: 0 16px 48px rgba(0,0,0,0.13); transform: translateY(-4px); }
    .product-card-header {
      background: linear-gradient(135deg, #1c1917, #1e293b);
      padding: 1rem 1.5rem;
      display: flex; align-items: center; justify-content: space-between;
    }
    .product-card-header-left { display: flex; align-items: center; gap: 0.75rem; }
    .product-num {
      width: 2.25rem; height: 2.25rem; border-radius: 9999px;
      background: #fbbf24; color: #1c1917;
      display: flex; align-items: center; justify-content: center;
      font-size: 0.875rem; font-weight: 900; flex-shrink: 0;
    }
    .product-card-name { color: #fff; font-weight: 700; font-size: 1.0625rem; }
    .product-badge {
      padding: 0.25rem 0.75rem;
      background: #fbbf24; color: #1c1917; border-radius: 9999px;
      font-size: 0.7rem; font-weight: 900; text-transform: uppercase; letter-spacing: 0.08em;
    }
    .product-card-body { padding: 1.5rem; }
    .product-card-cols { display: flex; flex-direction: column; gap: 1.5rem; }
    @media (min-width: 640px) { .product-card-cols { flex-direction: row; } }
    .product-image-col { flex-shrink: 0; }
    @media (min-width: 640px) { .product-image-col { width: 13rem; } }
    .product-image-box {
      background: #fafaf9; border: 1px solid #f5f5f4; border-radius: 1rem;
      height: 13rem; display: flex; align-items: center; justify-content: center;
      overflow: hidden; padding: 1rem;
    }
    .product-image-box img { max-height: 11rem; max-width: 100%; object-fit: contain; }
    .product-rating-row { margin-top: 0.75rem; text-align: center; }
    .product-rating-text { font-size: 0.75rem; color: #78716c; margin-top: 0.25rem; }
    .product-visit-btn {
      display: block; margin-top: 0.75rem; text-align: center;
      padding: 0.625rem 1rem;
      background: linear-gradient(135deg, #22c55e, #10b981);
      color: #fff; border-radius: 0.875rem; font-size: 0.8125rem; font-weight: 700;
      transition: all 0.2s;
    }
    .product-visit-btn:hover { background: linear-gradient(135deg, #16a34a, #059669); transform: translateY(-1px); }
    .product-details-col { flex: 1; min-width: 0; }
    .pros-cons {
      display: grid; grid-template-columns: 1fr; gap: 1rem;
      margin-bottom: 1.25rem; padding: 1rem;
      background: #fafaf9; border-radius: 1rem; overflow: hidden;
    }
    @media (min-width: 480px) { .pros-cons { grid-template-columns: 1fr 1fr; } }
    .pros-cons-label {
      font-size: 0.7rem; font-weight: 900; text-transform: uppercase; letter-spacing: 0.1em;
      margin-bottom: 0.75rem;
    }
    .pros-label { color: #065f46; }
    .cons-label { color: #991b1b; }
    .pros-cons ul { list-style: none; padding: 0; }
    .pros-cons li {
      display: flex; align-items: flex-start; gap: 0.5rem;
      font-size: 0.875rem; color: #44403c; line-height: 1.5; margin-bottom: 0.5rem;
    }
    .pros-cons li svg { width: 1rem; height: 1rem; flex-shrink: 0; margin-top: 0.125rem; }
    .pro-icon { color: #10b981; }
    .con-icon { color: #f87171; }
    .specs-label {
      font-size: 0.7rem; font-weight: 900; text-transform: uppercase; letter-spacing: 0.1em;
      color: #44403c; margin-bottom: 0.75rem;
    }
    .specs-table { border: 1px solid #e7e5e4; border-radius: 1rem; overflow: hidden; }
    .specs-table table { width: 100%; font-size: 0.875rem; border-collapse: collapse; }
    .specs-table tr:nth-child(even) { background: #fafaf9; }
    .specs-table td { padding: 0.625rem 1rem; }
    .specs-table td:first-child {
      font-weight: 600; color: #292524; width: 40%;
      border-right: 1px solid #e7e5e4; text-transform: capitalize;
    }
    .specs-table td:last-child { color: #d97706; font-weight: 500; }
    .our-take {
      margin-top: 1rem; padding: 1.25rem 1.5rem;
      background: #eff6ff; border: 1px solid #dbeafe; border-radius: 1rem;
    }
    .our-take-label {
      font-size: 0.7rem; font-weight: 900; text-transform: uppercase; letter-spacing: 0.1em;
      color: #1d4ed8; margin-bottom: 0.5rem;
    }
    .our-take p { color: #44403c; line-height: 1.75; font-size: 1rem; word-break: break-word; }

    /* ── CTA Box ──────────────────────────────────── */
    .cta-box {
      margin: 3rem 0; padding: 2rem;
      background: linear-gradient(135deg, #1c1917 0%, #1e293b 50%, #1c1917 100%);
      border-radius: 1.5rem; text-align: center; color: #fff;
    }
    .cta-hidden { display: none; }
    .cta-box h3 { font-size: 1.5rem; font-weight: 700; margin-bottom: 0.75rem; }
    .cta-box p { color: #d6d3d1; margin-bottom: 1.5rem; }
    .cta-buttons { display: flex; flex-wrap: wrap; gap: 1rem; justify-content: center; }
    .cta-btn-primary {
      padding: 0.75rem 1.5rem;
      background: #22c55e; color: #fff; border-radius: 1rem;
      font-weight: 600; transition: background 0.2s;
    }
    .cta-btn-primary:hover { background: #16a34a; }
    .cta-btn-secondary {
      padding: 0.75rem 1.5rem;
      background: rgba(255,255,255,0.15); color: #fff; border-radius: 1rem;
      font-weight: 600; transition: background 0.2s;
    }
    .cta-btn-secondary:hover { background: rgba(255,255,255,0.25); }

    /* ── Related Posts ────────────────────────────── */
    .related { margin-top: 4rem; }
    .related h3 { font-size: 1.5rem; font-weight: 700; color: #1c1917; margin-bottom: 2rem; }
    .related-grid { display: grid; grid-template-columns: 1fr; gap: 1.5rem; }
    @media (min-width: 768px) { .related-grid { grid-template-columns: repeat(3, 1fr); } }
    .related-card {
      background: #fafaf9; border-radius: 1rem; overflow: hidden;
      cursor: pointer; transition: box-shadow 0.3s;
    }
    .related-card:hover { box-shadow: 0 8px 32px rgba(0,0,0,0.12); }
    .related-card img { width: 100%; height: 9rem; object-fit: cover; transition: transform 0.3s; }
    .related-card:hover img { transform: scale(1.05); }
    .related-card-body { padding: 1rem; }
    .related-card h4 { font-weight: 700; color: #1c1917; font-size: 0.875rem; margin-bottom: 0.25rem; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
    .related-card span { font-size: 0.75rem; color: #78716c; }

    /* ── Footer ───────────────────────────────────── */
    footer {
      background: linear-gradient(135deg, #1c1917 0%, #1e293b 50%, #1c1917 100%);
      color: #fff; position: relative; overflow: hidden;
    }
    footer::before {
      content: '';
      position: absolute; top: 5rem; left: 5rem;
      width: 24rem; height: 24rem;
      background: radial-gradient(circle, rgba(251,191,36,0.08) 0%, transparent 70%);
      pointer-events: none;
    }
    footer::after {
      content: '';
      position: absolute; bottom: 5rem; right: 5rem;
      width: 24rem; height: 24rem;
      background: radial-gradient(circle, rgba(96,165,250,0.07) 0%, transparent 70%);
      pointer-events: none;
    }
    .footer-inner {
      max-width: 1280px; margin: 0 auto;
      padding: 5rem 1.5rem 2rem; position: relative; z-index: 1;
    }
    .footer-grid {
      display: grid;
      grid-template-columns: 1fr;
      gap: 3rem;
      margin-bottom: 4rem;
    }
    @media (min-width: 768px) { .footer-grid { grid-template-columns: 1fr 1fr; } }
    @media (min-width: 1024px) { .footer-grid { grid-template-columns: 2fr 1fr 1fr; } }
    .footer-brand .footer-logo { display: flex; align-items: center; gap: 0.75rem; margin-bottom: 1.5rem; }
    .footer-brand .footer-logo-icon { padding: 0.75rem; background: linear-gradient(135deg, #44403c, #1e293b); border-radius: 1rem; }
    .footer-brand .footer-logo-icon svg { width: 1.75rem; height: 1.75rem; }
    .footer-brand .footer-logo-icon svg path { stroke: #fff; }
    .footer-brand h2 { font-size: 1.5rem; font-weight: 700; }
    .footer-brand .footer-tagline { font-size: 0.875rem; color: #a8a29e; font-weight: 500; }
    .footer-brand p { color: #d6d3d1; line-height: 1.7; font-weight: 300; font-size: 1.0625rem; max-width: 28rem; margin-bottom: 1.5rem; }
    .footer-contact-btns { display: flex; flex-wrap: wrap; gap: 1rem; }
    .footer-wa {
      display: inline-flex; align-items: center; gap: 0.5rem;
      padding: 0.625rem 1.25rem;
      background: linear-gradient(135deg, #22c55e, #10b981); color: #fff;
      border-radius: 1rem; font-weight: 600; font-size: 0.875rem; transition: all 0.3s;
    }
    .footer-wa:hover { background: linear-gradient(135deg, #16a34a, #059669); transform: translateY(-2px); }
    .footer-email {
      display: inline-flex; align-items: center; gap: 0.5rem;
      padding: 0.625rem 1.25rem;
      background: rgba(255,255,255,0.1); border: 1px solid rgba(255,255,255,0.2); color: #fff;
      border-radius: 1rem; font-weight: 600; font-size: 0.875rem; transition: all 0.3s;
    }
    .footer-email:hover { background: rgba(255,255,255,0.18); }
    .footer-col h3 { font-size: 1.125rem; font-weight: 700; margin-bottom: 1.5rem; }
    .footer-col ul { list-style: none; }
    .footer-col ul li { margin-bottom: 1rem; }
    .footer-col ul li a {
      color: #d6d3d1; font-weight: 500; font-size: 0.9375rem;
      transition: color 0.2s; display: flex; align-items: center; gap: 0.5rem;
    }
    .footer-col ul li a:hover { color: #fff; padding-left: 0.25rem; }
    .footer-urgent {
      background: rgba(251,191,36,0.1); border: 1px solid rgba(251,191,36,0.25);
      border-radius: 1.5rem; padding: 2rem; text-align: center; margin-bottom: 3rem;
    }
    .footer-urgent .urgent-pill {
      display: inline-flex; align-items: center; gap: 0.5rem;
      padding: 0.375rem 1rem; background: rgba(251,191,36,0.15);
      border-radius: 9999px; margin-bottom: 1rem;
      color: #fde68a; font-weight: 600; font-size: 0.875rem;
    }
    .footer-urgent h3 { font-size: 1.25rem; font-weight: 700; margin-bottom: 0.5rem; }
    .footer-urgent p { color: #d6d3d1; font-weight: 300; }
    .footer-bottom {
      border-top: 1px solid rgba(87,83,78,0.4);
      padding-top: 2rem;
      display: flex; flex-wrap: wrap; gap: 1rem;
      justify-content: space-between; align-items: center;
    }
    .footer-bottom p { color: #a8a29e; font-size: 0.875rem; font-weight: 300; }
    .footer-links { display: flex; flex-wrap: wrap; gap: 1.5rem; }
    .footer-links a { color: #a8a29e; font-size: 0.875rem; font-weight: 500; transition: color 0.2s; }
    .footer-links a:hover { color: #fff; text-decoration: underline; }

    /* ── Floating Action Button ───────────────────── */
    #fab {
      position: fixed; bottom: 1.5rem; right: 1.5rem;
      width: 3.5rem; height: 3.5rem; border-radius: 9999px;
      background: linear-gradient(135deg, #1c1917, #1e293b);
      color: #fff; box-shadow: 0 8px 32px rgba(0,0,0,0.3);
      display: flex; align-items: center; justify-content: center;
      cursor: pointer; z-index: 900; border: none;
      opacity: 0; transform: translateY(20px) scale(0.8);
      transition: opacity 0.3s, transform 0.3s;
    }
    #fab.visible { opacity: 1; transform: translateY(0) scale(1); }
    #fab:hover { transform: scale(1.1); }
    #fab svg { width: 1.5rem; height: 1.5rem; }
    #fab-dot {
      position: absolute; top: -2px; right: -2px;
      width: 1rem; height: 1rem; background: #ef4444; border-radius: 9999px;
      display: flex; align-items: center; justify-content: center;
    }
    #fab-dot::after {
      content: ''; width: 6px; height: 6px;
      background: #fff; border-radius: 9999px; animation: pulse 2s infinite;
    }
    @keyframes pulse { 0%,100%{opacity:1;transform:scale(1)} 50%{opacity:0.7;transform:scale(1.2)} }

    /* ── Chat Widget ──────────────────────────────── */
    #chat-widget {
      position: fixed; bottom: 6.5rem; right: 1.5rem;
      width: 20rem; max-width: calc(100vw - 3rem);
      z-index: 950; background: #fff; border-radius: 1.5rem;
      box-shadow: 0 16px 64px rgba(0,0,0,0.18); border: 1px solid #e7e5e4;
      overflow: hidden;
      opacity: 0; transform: translateY(20px) scale(0.9);
      transition: opacity 0.3s, transform 0.3s;
      pointer-events: none;
    }
    #chat-widget.open { opacity: 1; transform: translateY(0) scale(1); pointer-events: all; }
    .chat-header {
      background: linear-gradient(135deg, #1c1917, #1e293b);
      padding: 1rem; display: flex; align-items: center; justify-content: space-between;
    }
    .chat-header-left { display: flex; align-items: center; gap: 0.75rem; }
    .chat-header-icon { padding: 0.5rem; background: rgba(255,255,255,0.15); border-radius: 0.75rem; }
    .chat-header-icon svg { width: 1.25rem; height: 1.25rem; color: #fff; }
    .chat-title { font-weight: 700; font-size: 1.0625rem; color: #fff; }
    .chat-subtitle { font-size: 0.8125rem; color: #d6d3d1; font-weight: 300; }
    .chat-close { padding: 0.5rem; background: none; border: none; cursor: pointer; color: #fff; border-radius: 0.75rem; }
    .chat-close:hover { background: rgba(255,255,255,0.1); }
    .chat-close svg { width: 1.25rem; height: 1.25rem; }
    .chat-body { padding: 1.5rem; }
    .chat-greeting { color: #44403c; font-weight: 500; margin-bottom: 1rem; }
    .chat-options { display: flex; flex-direction: column; gap: 0.75rem; }
    .chat-option {
      display: flex; align-items: center; gap: 0.75rem;
      padding: 1rem; border-radius: 1rem; cursor: pointer;
      border: none; width: 100%; text-align: left; transition: all 0.2s;
    }
    .chat-option-wa { background: #f0fdf4; border: 1px solid rgba(34,197,94,0.2); }
    .chat-option-wa:hover { background: #dcfce7; }
    .chat-option-email { background: #fafaf9; border: 1px solid rgba(87,83,78,0.2); }
    .chat-option-email:hover { background: #f5f5f4; }
    .chat-option-icon { padding: 0.5rem; border-radius: 0.75rem; flex-shrink: 0; }
    .chat-option-icon svg { width: 1.25rem; height: 1.25rem; color: #fff; }
    .icon-wa { background: #22c55e; }
    .icon-email { background: #44403c; }
    .chat-option-title { font-weight: 700; color: #1c1917; font-size: 0.9375rem; }
    .chat-option-sub { font-size: 0.8125rem; color: #57534e; }
    .chat-footer { padding: 1rem 1.5rem; border-top: 1px solid #f5f5f4; font-size: 0.75rem; color: #78716c; text-align: center; line-height: 1.6; }

    /* ── Utilities ────────────────────────────────── */
    .icon { display: inline-block; }
    svg { display: inline-block; vertical-align: middle; }

